create table if not exists public.impersonation_sessions (
  id uuid primary key default gen_random_uuid(), impersonated_id uuid not null references auth.users(id) on delete cascade,
  impersonated_profile jsonb not null default '{}'::jsonb, target_id uuid not null references auth.users(id) on delete cascade,
  target_profile jsonb not null default '{}'::jsonb, status text not null check (status in ('pending','declined','waiting','active','ended')),
  duration_ms bigint not null, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()),
  accepted_at timestamptz, started_at timestamptz, expires_at timestamptz, ended_at timestamptz, ended_by text,
  guess_text text, guess_correct boolean, revealed boolean not null default false, participants uuid[] not null default '{}'
);
create index if not exists impersonation_sessions_participants on public.impersonation_sessions using gin(participants);
create index if not exists impersonation_sessions_status on public.impersonation_sessions(status, updated_at desc);
create table if not exists public.impersonation_secrets (session_id uuid primary key references public.impersonation_sessions(id) on delete cascade, impersonator_id uuid not null references auth.users(id) on delete cascade, impersonator_profile jsonb not null default '{}', created_at timestamptz not null default timezone('utc',now()));
create table if not exists public.impersonation_messages (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.impersonation_sessions(id) on delete cascade, role text not null check (role in ('impersonator','target')), text text not null, created_at timestamptz not null default timezone('utc',now()));
create index if not exists impersonation_messages_cursor on public.impersonation_messages(session_id, created_at asc, id asc);
create table if not exists public.impersonation_prompts (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.impersonation_sessions(id) on delete cascade, audience text not null check (audience in ('impersonator','target')), text text not null, created_at timestamptz not null default timezone('utc',now()));
create index if not exists impersonation_prompts_cursor on public.impersonation_prompts(session_id, created_at asc, id asc);
alter table public.impersonation_sessions enable row level security; alter table public.impersonation_secrets enable row level security; alter table public.impersonation_messages enable row level security; alter table public.impersonation_prompts enable row level security;
create policy impersonation_sessions_member on public.impersonation_sessions for all to authenticated using (auth.uid() = any(participants) or exists(select 1 from public.impersonation_secrets s where s.session_id=impersonation_sessions.id and s.impersonator_id=auth.uid())) with check (auth.uid() = any(participants) or exists(select 1 from public.impersonation_secrets s where s.session_id=impersonation_sessions.id and s.impersonator_id=auth.uid()));
create policy impersonation_secrets_owner on public.impersonation_secrets for all to authenticated using (impersonator_id=auth.uid()) with check (impersonator_id=auth.uid());
create policy impersonation_messages_member on public.impersonation_messages for all to authenticated using (exists(select 1 from public.impersonation_sessions s where s.id=session_id and (auth.uid()=any(s.participants) or exists(select 1 from public.impersonation_secrets x where x.session_id=s.id and x.impersonator_id=auth.uid())))) with check (exists(select 1 from public.impersonation_sessions s where s.id=session_id and (auth.uid()=any(s.participants) or exists(select 1 from public.impersonation_secrets x where x.session_id=s.id and x.impersonator_id=auth.uid()))));
create policy impersonation_prompts_member on public.impersonation_prompts for all to authenticated using (exists(select 1 from public.impersonation_sessions s where s.id=session_id and (auth.uid()=any(s.participants) or exists(select 1 from public.impersonation_secrets x where x.session_id=s.id and x.impersonator_id=auth.uid())))) with check (exists(select 1 from public.impersonation_sessions s where s.id=session_id and (auth.uid()=any(s.participants) or exists(select 1 from public.impersonation_secrets x where x.session_id=s.id and x.impersonator_id=auth.uid()))));
grant select,insert,update,delete on public.impersonation_sessions, public.impersonation_secrets, public.impersonation_messages, public.impersonation_prompts to authenticated;
